package br.com.cuidaplus.api.care_contract;
import br.com.cuidaplus.api.profile.AssistedPerson; import br.com.cuidaplus.api.service_request.ServiceRequest; import br.com.cuidaplus.api.user.User; import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="care_contracts") public class CareContract{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@OneToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="service_request_id")private ServiceRequest serviceRequest;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="responsible_user_id")private User responsibleUser;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="caregiver_user_id")private User caregiverUser;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="assisted_person_id")private AssistedPerson assistedPerson;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private CareContractStatus status;@Column(nullable=false)private LocalDate startDate;private LocalDate endDate;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;@PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void update(){updatedAt=Instant.now();}public UUID getId(){return id;}public void setServiceRequest(ServiceRequest v){serviceRequest=v;}public void setResponsibleUser(User v){responsibleUser=v;}public void setCaregiverUser(User v){caregiverUser=v;}public void setAssistedPerson(AssistedPerson v){assistedPerson=v;}public void setStatus(CareContractStatus v){status=v;}public CareContractStatus getStatus(){return status;}public void setStartDate(LocalDate v){startDate=v;}public void setEndDate(LocalDate v){endDate=v;}}
